/**
 * Which Minecraft server type × version combinations actually exist — for the
 * deploy wizard, the Settings tab and the server-side checks in
 * lib/game-order.ts (gameOrderQuote) and lib/actions-game-config.ts
 * (saveGameConfig).
 *
 * Source order per type: the mirror's index.json (fresh = updated < 48 h ago),
 * else a light live call to the upstream's own version list (4 s timeout),
 * else UNKNOWN. Unknown never blocks an order — it only means we can't say
 * "that doesn't exist" with confidence, which is the pre-mirror behaviour.
 */
import { mirrorReady, mirrorRoot } from "./config";
import { readIndex } from "./store";
import { ORDERABLE_TYPES, type OrderableType, type TypeIndex } from "./types";
import { nearestVersion, sortVersionsDesc } from "./versions";
import { pickBuild } from "./plan";

export interface TypeAvailability {
  type: OrderableType;
  /** Newest first. Every version with at least one real build. */
  versions: string[];
  /** Versions that only have beta/"latest-not-recommended" builds (Forge/NeoForge lines without a recommended build yet). */
  experimental: string[];
  /** What "Always latest" resolves to right now. */
  latest: { version: string; build: string | null } | null;
  /** Versions we hold an exact jar for (restarts never depend on upstream). */
  mirrored: string[];
  source: "mirror" | "upstream";
  checkedAt: string;
}

export interface Availability {
  status: "ok" | "partial" | "unknown";
  types: Partial<Record<OrderableType, TypeAvailability>>;
}

export const LABELS: Record<OrderableType, string> = { vanilla: "Vanilla", paper: "Paper", purpur: "Purpur", fabric: "Fabric", forge: "Forge" };
const FRESH_MS = 48 * 3600_000;

export function fromIndex(type: OrderableType, ix: TypeIndex): TypeAvailability {
  const versions: string[] = [];
  const experimental: string[] = [];
  const mirrored: string[] = [];
  for (const v of ix.order) {
    const ver = ix.versions[v];
    if (!ver) continue;
    const real = ver.builds.filter((b) => !b.gone && b.channel !== "self-built");
    const selfBuilt = ver.builds.some((b) => b.channel === "self-built" && b.mirrored);
    if (!real.length && !selfBuilt) continue;
    versions.push(v);
    if (!real.some((b) => b.channel === "stable")) experimental.push(v);
    if (pickBuild(ver, { allowSelfBuilt: true })) mirrored.push(v);
  }
  const latestV = versions.find((v) => !experimental.includes(v)) ?? versions[0] ?? null;
  const latestVer = latestV ? ix.versions[latestV] : undefined;
  return {
    type,
    versions,
    experimental,
    latest: latestV ? { version: latestV, build: latestVer?.latestStableBuild ?? latestVer?.latestBuild ?? null } : null,
    mirrored,
    source: "mirror",
    checkedAt: ix.updatedAt,
  };
}

// --- live upstream fallback (version lists only, no downloads) ---------------

async function getJson<T>(url: string, fetchImpl: typeof fetch): Promise<T> {
  const r = await fetchImpl(url, {
    headers: { "User-Agent": "NxeonMcMirror/1.0 (+https://nxeon.cloud; ops@nxeon.cloud)", Accept: "application/json" },
    signal: AbortSignal.timeout(4000),
  });
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  return (await r.json()) as T;
}

export async function liveVersions(type: OrderableType, fetchImpl: typeof fetch = fetch): Promise<TypeAvailability> {
  let versions: string[] = [];
  let experimental: string[] = [];
  switch (type) {
    case "vanilla": {
      const m = await getJson<{ versions: { id: string; type: string }[] }>("https://piston-meta.mojang.com/mc/game/version_manifest_v2.json", fetchImpl);
      versions = m.versions.filter((v) => v.type === "release").map((v) => v.id);
      break;
    }
    case "paper": {
      try {
        const r = await getJson<{ versions: { version: { id: string }; builds: number[] }[] }>("https://fill.papermc.io/v3/projects/paper/versions", fetchImpl);
        versions = r.versions.filter((v) => v.builds?.length).map((v) => v.version.id);
      } catch {
        const r = await getJson<{ versions: string[] }>("https://api.papermc.io/v2/projects/paper", fetchImpl);
        versions = r.versions;
      }
      break;
    }
    case "purpur": {
      versions = (await getJson<{ versions: string[] }>("https://api.purpurmc.org/v2/purpur", fetchImpl)).versions;
      break;
    }
    case "fabric": {
      versions = (await getJson<{ version: string; stable: boolean }[]>("https://meta.fabricmc.net/v2/versions/game", fetchImpl)).filter((g) => g.stable).map((g) => g.version);
      break;
    }
    case "forge": {
      const p = await getJson<{ promos: Record<string, string> }>("https://files.minecraftforge.net/net/minecraftforge/forge/promotions_slim.json", fetchImpl);
      const rec = new Set<string>();
      const all = new Set<string>();
      for (const k of Object.keys(p.promos)) {
        const m = /^(.+)-(recommended|latest)$/.exec(k);
        if (!m) continue;
        all.add(m[1]);
        if (m[2] === "recommended") rec.add(m[1]);
      }
      versions = [...all];
      experimental = versions.filter((v) => !rec.has(v));
      break;
    }
  }
  versions = sortVersionsDesc(versions.filter((v) => /^\d+(\.\d+){1,3}$/.test(v)));
  const latest = versions.find((v) => !experimental.includes(v)) ?? versions[0] ?? null;
  return { type, versions, experimental, latest: latest ? { version: latest, build: null } : null, mirrored: [], source: "upstream", checkedAt: new Date().toISOString() };
}

// --- cached aggregate ---------------------------------------------------------

let cache: { at: number; value: Availability } | null = null;
const CACHE_MS = 10 * 60_000;

export async function getAvailability(opts: { root?: string; fetchImpl?: typeof fetch; noCache?: boolean; allowUpstream?: boolean } = {}): Promise<Availability> {
  if (!opts.noCache && cache && Date.now() - cache.at < CACHE_MS) return cache.value;
  const types: Availability["types"] = {};
  const ready = opts.root ? true : await mirrorReady();
  await Promise.all(
    ORDERABLE_TYPES.map(async (t) => {
      try {
        const ix = ready ? await readIndex(t, opts.root ?? mirrorRoot()) : null;
        if (ix && Date.now() - Date.parse(ix.updatedAt) < FRESH_MS && ix.order.length) {
          types[t] = fromIndex(t, ix);
          return;
        }
        if (opts.allowUpstream === false) return;
        types[t] = await liveVersions(t, opts.fetchImpl);
      } catch {
        /* unknown for this type */
      }
    }),
  );
  const n = Object.keys(types).length;
  const value: Availability = { status: n === ORDERABLE_TYPES.length ? "ok" : n ? "partial" : "unknown", types };
  // Don't pin a total failure for 10 minutes — retry on the next call after 1 min.
  cache = { at: n ? Date.now() : Date.now() - CACHE_MS + 60_000, value };
  return value;
}

export function _resetAvailabilityCache(): void {
  cache = null;
}

export type ComboCheck =
  | { ok: true; verified: boolean; resolved?: { version: string; build: string | null } }
  | { ok: false; message: string; suggestion: string | null };

/** Pure: check a combo against an Availability snapshot. */
export function checkComboIn(av: Availability, variant: string, version: string): ComboCheck {
  const t = (ORDERABLE_TYPES as readonly string[]).includes(variant) ? av.types[variant as OrderableType] : undefined;
  if (!t) return { ok: true, verified: false };
  if (version === "LATEST") return { ok: true, verified: true, resolved: t.latest ?? undefined };
  if (t.versions.includes(version)) return { ok: true, verified: true };
  const suggestion = nearestVersion(version, t.versions);
  const label = LABELS[variant as OrderableType];
  return {
    ok: false,
    message: `${label} isn't available for Minecraft ${version}${suggestion ? ` — the nearest version ${label} supports is ${suggestion}` : ""}. Pick another version or server type.`,
    suggestion,
  };
}

export async function checkMinecraftCombo(variant: string, version: string): Promise<ComboCheck> {
  try {
    return checkComboIn(await getAvailability(), variant, version);
  } catch {
    return { ok: true, verified: false };
  }
}
