"use client";

import { useEffect, useState } from "react";
import { nearestVersion } from "@/lib/mcjars/versions";

/**
 * Client view of /api/mc-versions — which Minecraft type × version combos
 * really exist. `state: "checking"` while loading; "unknown" when neither the
 * mirror nor upstream could answer (the UI then shows every version and lets
 * the server-side check have the final word, exactly as before).
 */
export type McTypeVersions = {
  versions: string[];
  experimental: string[];
  latest: { version: string; build: string | null } | null;
  mirrored: number;
  source: "mirror" | "upstream";
};
export type McVersions = { state: "checking" | "ok" | "unknown"; types: Record<string, McTypeVersions> };

let shared: Promise<McVersions> | null = null;

function load(): Promise<McVersions> {
  shared ??= fetch("/api/mc-versions")
    .then((r) => (r.ok ? r.json() : Promise.reject(new Error(String(r.status)))))
    .then((j: { status: string; types: Record<string, McTypeVersions> }) => ({
      state: j.status === "unknown" ? ("unknown" as const) : ("ok" as const),
      types: j.types ?? {},
    }))
    .catch(() => {
      shared = null; // allow a retry on next mount
      return { state: "unknown" as const, types: {} };
    });
  return shared;
}

export function useMcVersions(enabled: boolean): McVersions {
  const [v, setV] = useState<McVersions>({ state: "checking", types: {} });
  useEffect(() => {
    if (!enabled) return;
    let live = true;
    load().then((r) => live && setV(r));
    return () => {
      live = false;
    };
  }, [enabled]);
  return v;
}

/** Options for the VERSION select, filtered to what `variant` supports. Keeps `current` visible (flagged) even if unsupported. */
export function filterVersionOptions(
  options: { value: string; label: string }[],
  mv: McVersions,
  variant: string,
  current: string,
): { options: { value: string; label: string }[]; supported: boolean | null; latestLabel: string | null; nearest: string | null } {
  const t = mv.types[variant];
  if (mv.state !== "ok" || !t) return { options, supported: null, latestLabel: null, nearest: null };
  const ok = new Set(t.versions);
  const exp = new Set(t.experimental);
  const out = options
    .filter((o) => o.value === "LATEST" || ok.has(o.value) || o.value === current)
    .map((o) => {
      if (o.value === "LATEST") return { ...o, label: t.latest ? `Always latest — currently ${t.latest.version}${t.latest.build && t.latest.build !== t.latest.version ? ` (build ${t.latest.build})` : ""}` : o.label };
      if (!ok.has(o.value)) return { ...o, label: `${o.label} — not available for this type` };
      return exp.has(o.value) ? { ...o, label: `${o.label} (beta builds only)` } : o;
    });
  const supported = current === "LATEST" || ok.has(current);
  const nearest = supported ? null : nearestVersion(current, t.versions);
  const latestLabel = t.latest ? `${t.latest.version}${t.latest.build && t.latest.build !== t.latest.version ? ` · build ${t.latest.build}` : ""}` : null;
  return { options: out, supported, latestLabel, nearest };
}

