/** "LATEST" → the newest stable version of this type that has a pickable mirrored build. */
export function resolveVersion(ix: TypeIndex, want: string, opts: PickOpts = {}): string | null {
  if (want !== "LATEST") return ix.versions[want] ? want : null;
  for (const v of ix.order) {
    const ver = ix.versions[v];
    if (ver?.channel === "stable" && pickBuild(ver, opts)) return v;
  }
  return null;
}

/** For R's auto-update (worker/game-update.ts): newest mirrored stable version+build of a type. */
export async function newestPinnable(type: McType, root = mirrorRoot()): Promise<{ mcVersion: string; build: string; sha256: string } | null> {
  const ix = await readIndex(type, root);
  if (!ix) return null;
  const v = resolveVersion(ix, "LATEST");
  const b = v ? pickBuild(ix.versions[v]) : null;
  return v && b?.sha256 ? { mcVersion: v, build: b.build, sha256: b.sha256 } : null;
}

/** Newest mirrored build for a FIXED version (auto-update within a version line: e.g. Paper 26.2 build 17 → 23). */
export async function newestBuildFor(type: McType, mcVersion: string, root = mirrorRoot()): Promise<{ build: string; sha256: string } | null> {
  const ix = await readIndex(type, root);
  const b = pickBuild(ix?.versions[mcVersion]);
  return b?.sha256 ? { build: b.build, sha256: b.sha256 } : null;
}

