/**
 * Which Minecraft VERSION the deploy wizard preselects for each server type.
 *
 * Pure and I/O-free so it is unit-tested (test/mc-default-version.test.ts) and
 * so the preselection and the "Latest <type> right now: X" hint can never
 * disagree: both read the same `latest` the availability layer
 * (lib/mcjars/availability.ts → /api/mc-versions) computes.
 *
 *  - vanilla / paper / purpur: the type's own latest STABLE release. (Paper's
 *    newest line is often beta-only, so its latest can lag Vanilla's — that is
 *    deliberately what the hint says too.)
 *  - fabric / forge (and anything modded): the conservative pin
 *    MODDED_DEFAULT_VERSION (1.21.1 — where most modpacks target), but only
 *    when that loader really has a stable build for it; otherwise the type's
 *    latest. Mods lag Mojang by months, so floating to newest would break them.
 *  - No data yet (checking / upstream unreachable): vanilla gets the newest
 *    release of the static snapshot in game-config.ts, everything else the
 *    conservative pin — both deterministic, so SSR and the first client render
 *    agree (no hydration mismatch). The server re-validates type x version
 *    before payment regardless.
 *
 * A concrete number is preselected, never itzg's "LATEST": provisioning pins a
 * concrete jar anyway (lib/mcjars/pin.ts) and the hint names a concrete number.
 */
export const MODDED_DEFAULT_VERSION = "1.21.1";

export type McTypeLike = { versions: string[]; experimental: string[]; latest: { version: string } | null };
export type McVersionsLike = { state: "checking" | "ok" | "unknown"; types: Record<string, McTypeLike> };

const FOLLOWS_LATEST = new Set(["vanilla", "paper", "purpur"]);

export function isModdedVariant(variant: string): boolean {
  return !FOLLOWS_LATEST.has(variant);
}

export function defaultMinecraftVersion(variant: string, mv: McVersionsLike, staticNewest: string): string {
  const v = variant || "vanilla";
  const t = mv.state === "ok" ? mv.types[v] : undefined;
  if (!FOLLOWS_LATEST.has(v)) {
    if (t && t.versions.includes(MODDED_DEFAULT_VERSION) && !t.experimental.includes(MODDED_DEFAULT_VERSION)) return MODDED_DEFAULT_VERSION;
    if (t?.latest) return t.latest.version;
    return MODDED_DEFAULT_VERSION;
  }
  if (t?.latest) return t.latest.version;
  return v === "vanilla" ? staticNewest : MODDED_DEFAULT_VERSION;
}

/**
 * The VERSION the wizard should write into the order's config now, or null to
 * leave it alone. `lastAuto` is the value this logic wrote last time: the
 * field follows the server type only while it is still unset or still equals
 * that auto value — a version the customer picked (or a preset set) is kept.
 */
export function nextAutoVersion(args: { current: string | undefined; lastAuto: string | null; target: string }): string | null {
  const { current, lastAuto, target } = args;
  if (current === target) return null;
  if (current === undefined || current === "" || current === lastAuto) return target;
  return null;
}
