/**
 * Deploy-wizard Minecraft VERSION preselection (lib/mcjars/default-version.ts).
 *   npx tsx --test test/mc-default-version.test.ts
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { defaultMinecraftVersion, nextAutoVersion, MODDED_DEFAULT_VERSION, type McVersionsLike } from "../lib/mcjars/default-version";
import { filterVersionOptions, type McVersions } from "../components/customer/useMcVersions";
import { MINECRAFT_STATIC_NEWEST_RELEASE } from "../lib/game-config";

const ok = (over: Partial<McVersionsLike["types"]> = {}): McVersionsLike => ({
  state: "ok",
  types: {
    vanilla: { versions: ["26.3", "26.2", "1.21.1"], experimental: [], latest: { version: "26.3" } },
    paper: { versions: ["26.3", "26.2", "1.21.1"], experimental: ["26.3"], latest: { version: "26.2" } },
    purpur: { versions: ["26.3", "1.21.1"], experimental: [], latest: { version: "26.3" } },
    fabric: { versions: ["26.3", "1.21.1"], experimental: [], latest: { version: "26.3" } },
    forge: { versions: ["26.3", "26.2", "1.21.1"], experimental: ["26.3"], latest: { version: "26.2" } },
    ...over,
  },
});
const STATIC = "26.3";

test("vanilla / paper / purpur preselect the type's own latest (same as the hint)", () => {
  const mv = ok();
  assert.equal(defaultMinecraftVersion("vanilla", mv, STATIC), "26.3");
  assert.equal(defaultMinecraftVersion("paper", mv, STATIC), "26.2");
  assert.equal(defaultMinecraftVersion("purpur", mv, STATIC), "26.3");
  // preselection === hint for every follow-latest type
  for (const v of ["vanilla", "paper", "purpur"]) {
    const f = filterVersionOptions([{ value: "LATEST", label: "x" }], mv as McVersions, v, "x");
    assert.equal(f.latestLabel, defaultMinecraftVersion(v, mv, STATIC));
  }
});

test("modded loaders stay on the conservative pin when it genuinely exists", () => {
  const mv = ok();
  assert.equal(defaultMinecraftVersion("fabric", mv, STATIC), MODDED_DEFAULT_VERSION);
  assert.equal(defaultMinecraftVersion("forge", mv, STATIC), MODDED_DEFAULT_VERSION);
});

test("modded pin that does not exist (or is beta-only) falls back to the loader's latest", () => {
  const mv = ok({ fabric: { versions: ["26.3"], experimental: [], latest: { version: "26.3" } }, forge: { versions: ["1.21.1", "26.2"], experimental: ["1.21.1"], latest: { version: "26.2" } } });
  assert.equal(defaultMinecraftVersion("fabric", mv, STATIC), "26.3");
  assert.equal(defaultMinecraftVersion("forge", mv, STATIC), "26.2");
});

test("no data (checking / unknown): deterministic fallbacks, vanilla = static newest release", () => {
  for (const state of ["checking", "unknown"] as const) {
    const mv: McVersionsLike = { state, types: {} };
    assert.equal(defaultMinecraftVersion("vanilla", mv, STATIC), STATIC);
    assert.equal(defaultMinecraftVersion("", mv, STATIC), STATIC);
    for (const v of ["paper", "purpur", "fabric", "forge"]) assert.equal(defaultMinecraftVersion(v, mv, STATIC), MODDED_DEFAULT_VERSION);
  }
});

test("the static snapshot's newest release is a real, non-LATEST version", () => {
  assert.match(MINECRAFT_STATIC_NEWEST_RELEASE, /^\d+(\.\d+)+$/);
});

test("nextAutoVersion follows the type while unset/auto, keeps an explicit pick", () => {
  assert.equal(nextAutoVersion({ current: undefined, lastAuto: null, target: "26.3" }), "26.3");
  assert.equal(nextAutoVersion({ current: "26.3", lastAuto: "26.3", target: "26.3" }), null);
  // switch vanilla -> fabric while still on the auto value: follows
  assert.equal(nextAutoVersion({ current: "26.3", lastAuto: "26.3", target: "1.21.1" }), "1.21.1");
  // customer picked 1.20.1: never overridden, in either direction
  assert.equal(nextAutoVersion({ current: "1.20.1", lastAuto: "26.3", target: "1.21.1" }), null);
  assert.equal(nextAutoVersion({ current: "1.20.1", lastAuto: null, target: "26.3" }), null);
  // live data arrives after the fallback was written: auto value is refreshed
  assert.equal(nextAutoVersion({ current: "26.2", lastAuto: "26.2", target: "26.3" }), "26.3");
});

test("1.21.1 is only labelled 'recommended for modded servers' for modded loaders", () => {
  const opts = [{ value: "1.21.1", label: "1.21.1" }];
  const mv = ok() as McVersions;
  const label = (v: string) => filterVersionOptions(opts, mv, v, "1.21.1").options[0].label;
  assert.equal(label("vanilla"), "1.21.1");
  assert.equal(label("paper"), "1.21.1");
  assert.match(label("fabric"), /recommended for modded/);
  assert.match(label("forge"), /recommended for modded/);
  assert.match(filterVersionOptions(opts, { state: "unknown", types: {} }, "forge", "1.21.1").options[0].label, /recommended for modded/);
});
EOF
