/**
 * Bake a customer's settings into the provisioning script so a fresh install / "Wipe & reinstall"
 * starts configured. Before the container's first run (when the image would otherwise copy the game's
 * example file) it builds server-settings.json FROM that example, read out of the image itself, patched
 * with the customer's values in python3 (so every other key keeps the game's own default), and writes
 * server-adminlist.json when admins were given. Any failure removes the half-written file so the image
 * falls back to its own defaults: a baking problem can never stop the server from provisioning.
 * `visibility.public` is never baked (no factorio.com credentials exist yet).
 */
export function applyFactorioSetup(setupScript: string, values: V | null | undefined): string {
  if (!values) return setupScript;
  const m = /factoriotools\/factorio(:[\w.-]+)?/.exec(setupScript);
  if (!m || !/docker run -d --name factorio/.test(setupScript)) return setupScript;
  const q = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;
  const edits = factorioEdits(values, undefined, { canPublish: false });
  const patch: Record<string, unknown> = {};
  for (const ed of edits) {
    if (ed.path.length === 1) patch[ed.path[0]] = ed.value;
    else {
      const o = (patch[ed.path[0]] ??= {}) as Record<string, unknown>;
      o[ed.path[1]] = ed.value;
    }
  }
  const b64 = Buffer.from(JSON.stringify(patch)).toString("base64");
  const py =
    "import json,sys,base64\n" +
    "p=sys.argv[2];d=json.load(open(p));u=json.loads(base64.b64decode(sys.argv[1]))\n" +
    "for k,v in u.items():\n" +
    "  d[k]={**d.get(k,{}),**v} if isinstance(v,dict) and isinstance(d.get(k),dict) else v\n" +
    "json.dump(d,open(p,'w'),indent=2)\n";
  const dir = "/opt/factorio/config";
  const file = FACTORIO_SETTINGS_PATH;
  const seed = `{ [ -f ${file} ] || { mkdir -p ${dir} && docker run --rm --entrypoint cat ${m[0]} ${FACTORIO_EXAMPLE_PATH} > ${file} && python3 -c ${q(py)} ${q(b64)} ${file} || rm -f ${file}; }; }`;
  const admins = factorioAdminList(values.admins);
  const adminSeed = admins.length
    ? ` && { [ -f ${FACTORIO_ADMINLIST_PATH} ] || printf '%s' ${q(JSON.stringify(admins))} > ${FACTORIO_ADMINLIST_PATH}; }`
    : "";
  return setupScript.replace("docker run -d --name factorio", () => `${seed}${adminSeed} && docker run -d --name factorio`);
}
